 50→// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
 51→// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
 52→// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
 53→// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
 54→// are correctly treated as new.
 55→func (s *PrePromptState) PreUntrackedFiles() []string {
 56→	if s == nil {
 57→		return nil
 58→	}
 59→	if s.UntrackedFiles == nil {
 60→		return []string{}
 61→	}
 62→	return s.UntrackedFiles
 63→}
