 65→// normalizePrePromptState migrates deprecated fields after loading from JSON.
 66→func (s *PrePromptState) normalizePrePromptState() {
 67→	// Migrate the oldest field to the intermediate field first
 68→	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
 69→		s.StepTranscriptStart = s.LastTranscriptLineCount
 70→	}
 71→	s.LastTranscriptLineCount = 0
 72→
 73→	// Migrate all deprecated fields to the unified TranscriptOffset
 74→	if s.TranscriptOffset == 0 {
 75→		if s.StepTranscriptStart > 0 {
 76→			s.TranscriptOffset = s.StepTranscriptStart
 77→		} else if s.StartMessageIndex > 0 {
 78→			s.TranscriptOffset = s.StartMessageIndex
 79→		}
 80→	}
 81→	s.StepTranscriptStart = 0
 82→	s.StartMessageIndex = 0
 83→}
