 85→// CapturePrePromptState captures current untracked files and transcript position before a prompt
 86→// and saves them to a state file.
 87→//
 88→// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
 89→// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
 90→// The sessionRef parameter is optional — if empty, transcript position won't be captured.
 91→//
 92→// Works correctly from any subdirectory within the repository.
 93→func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
 94→	if sessionID == "" {
 95→		sessionID = unknownSessionID
 96→	}
 97→
 98→	// Get absolute path for tmp directory
 99→	tmpDirAbs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
100→	if err != nil {
101→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
102→	}
103→
104→	// Create tmp directory if it doesn't exist
105→	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
106→		return fmt.Errorf("failed to create tmp directory: %w", err)
107→	}
108→
109→	// Get list of untracked files (excluding .entire directory itself)
110→	untrackedFiles, err := getUntrackedFilesForState(ctx)
111→	if err != nil {
112→		return fmt.Errorf("failed to get untracked files: %w", err)
113→	}
114→
115→	// Get transcript position using TranscriptAnalyzer if available
116→	var transcriptOffset int
117→	if analyzer, ok := ag.(agent.TranscriptAnalyzer); ok && sessionRef != "" {
118→		pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
119→		if posErr != nil {
120→			fmt.Fprintf(os.Stderr, "Warning: failed to get transcript position: %v\n", posErr)
121→		} else {
122→			transcriptOffset = pos
123→		}
124→	}
125→
126→	// Create state file
127→	stateFile := prePromptStateFile(ctx, sessionID)
128→	state := PrePromptState{
129→		SessionID:        sessionID,
130→		Timestamp:        time.Now().UTC().Format(time.RFC3339),
131→		UntrackedFiles:   untrackedFiles,
132→		TranscriptOffset: transcriptOffset,
133→	}
134→
135→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
136→	if err != nil {
137→		return fmt.Errorf("failed to marshal state: %w", err)
138→	}
139→
140→	if err := os.WriteFile(stateFile, data, 0o600); err != nil {
141→		return fmt.Errorf("failed to write state file: %w", err)
142→	}
143→
144→	fmt.Fprintf(os.Stderr, "Captured state before prompt: %d untracked files, transcript offset: %d\n",
145→		len(untrackedFiles), transcriptOffset)
146→	return nil
147→}
