182→// FileChanges holds categorized file changes from git status.
183→type FileChanges struct {
184→	Modified []string // Modified or staged files
185→	New      []string // Untracked files (filtered if previouslyUntracked provided)
186→	Deleted  []string // Deleted files (staged or unstaged)
187→}
