189→// DetectFileChanges returns categorized file changes from the current git status.
190→//
191→// previouslyUntracked controls new-file detection:
192→//   - nil: all untracked files go into New
193→//   - non-nil: only untracked files NOT in the pre-existing set go into New
194→//
195→// Modified includes both worktree and staging modified/added files.
196→// Deleted includes both staged and unstaged deletions.
197→// All results exclude .entire/ directory.
198→func DetectFileChanges(ctx context.Context, previouslyUntracked []string) (*FileChanges, error) {
199→	repo, err := openRepository(ctx)
200→	if err != nil {
201→		return nil, fmt.Errorf("failed to open repository: %w", err)
202→	}
203→
204→	worktree, err := repo.Worktree()
205→	if err != nil {
206→		return nil, fmt.Errorf("failed to get worktree: %w", err)
207→	}
208→
209→	status, err := worktree.Status()
210→	if err != nil {
211→		return nil, fmt.Errorf("failed to get status: %w", err)
212→	}
213→
214→	// Build set of pre-existing untracked files for quick lookup
215→	var preExisting map[string]bool
216→	if previouslyUntracked != nil {
217→		preExisting = make(map[string]bool, len(previouslyUntracked))
218→		for _, f := range previouslyUntracked {
219→			preExisting[f] = true
220→		}
221→	}
222→
223→	var changes FileChanges
224→	for file, st := range status {
225→		if paths.IsInfrastructurePath(file) {
226→			continue
227→		}
228→
229→		switch {
230→		case st.Worktree == git.Untracked:
231→			if preExisting != nil {
232→				if !preExisting[file] {
233→					changes.New = append(changes.New, file)
234→				}
235→			} else {
236→				changes.New = append(changes.New, file)
237→			}
238→		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
239→			changes.Deleted = append(changes.Deleted, file)
240→		case st.Worktree == git.Modified || st.Staging == git.Modified ||
241→			st.Worktree == git.Added || st.Staging == git.Added:
242→			changes.Modified = append(changes.Modified, file)
243→		}
244→	}
245→
246→	return &changes, nil
247→}
