330→// mergeUnique appends elements from extra into base, skipping duplicates already in base.
331→func mergeUnique(base, extra []string) []string {
332→	if len(extra) == 0 {
333→		return base
334→	}
335→	seen := make(map[string]bool, len(base))
336→	for _, s := range base {
337→		seen[s] = true
338→	}
339→	for _, s := range extra {
340→		if !seen[s] {
341→			seen[s] = true
342→			base = append(base, s)
343→		}
344→	}
345→	return base
346→}
