498→// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
499→// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
500→// When multiple pre-task files exist (nested subagents), returns the most recently
501→// modified one.
502→// Works correctly from any subdirectory within the repository.
503→func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
504→	tmpDirAbs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
505→	if err != nil {
506→		tmpDirAbs = paths.EntireTmpDir // Fallback to relative
507→	}
508→	entries, err := os.ReadDir(tmpDirAbs)
509→	if err != nil {
510→		return "", false
511→	}
512→
513→	var latestFile string
514→	var latestTime time.Time
515→
516→	for _, entry := range entries {
517→		if entry.IsDir() {
518→			continue
519→		}
520→		name := entry.Name()
521→		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
522→			continue
523→		}
524→
525→		// Check modification time for nested subagent handling
526→		info, err := entry.Info()
527→		if err != nil {
528→			continue
529→		}
530→		if latestFile == "" || info.ModTime().After(latestTime) {
531→			latestFile = name
532→			latestTime = info.ModTime()
533→		}
534→	}
535→
536→	if latestFile == "" {
537→		return "", false
538→	}
539→
540→	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
541→	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
542→	toolUseID = strings.TrimSuffix(toolUseID, ".json")
543→	return toolUseID, true
544→}
